-- Ligas pasadas: las fases ya jugadas se guardan cerradas (`terminada` = 1) y la web nunca vuelve a consultar
-- New Recruit para ellas. `fin`: último día de la fase (para mostrar las fechas sin calcular rondas).
ALTER TABLE liga_fases ADD COLUMN terminada INTEGER NOT NULL DEFAULT 0;
ALTER TABLE liga_fases ADD COLUMN fin TEXT;

-- Gran Liga 2026 (temporada ya jugada, del 1 de enero al 28 de febrero de 2026): leída una vez de la página pública
-- del torneo en New Recruit (rondas, cruces y resultados; en esa temporada no se subieron listas).
